const a={yingshe:{bibi:"Spot",bibidingdan:"Pesanan Spot",bibijiaoyi:"Dagangan Spot",jiamihuobi:"Kontrak Perpetual",miaoheyue:"Kontrak Penyelesaian",miaoheyuejiaoyi:"Dagangan Kontrak Penyelesaian"},jiaoyi:{xianhuomingcheng:"Nama Spot"},aurexion:{jianguanwenjian:"Dokumen Kawal Selia"},rwa_283:{jiaru:"Sertai RWA sekarang",biaoti:"Yuran ultra rendah, keselamatan cemerlang, had dagangan tinggi dan sokongan bertaraf dunia",xiazai:"Muat turun Aplikasi",jiaoyiliang:"Jumlah Dagangan 24 Jam",guanyu:"Mengenai RWA",guanyuxiangqing:"RWA merupakan salah satu penyedia penyelesaian pelaburan, khidmat nasihat dan pengurusan risiko terkemuka di dunia. Kami bertindak sebagai pemegang amanah kepada pelanggan kami. Kami membantu pelanggan melabur untuk masa depan, memberi inspirasi kepada pekerja dan menyokong komuniti tempatan.",jieshao:"Diiktiraf oleh majalah Fortune sebagai antara syarikat paling dikagumi di dunia",jieshaoxiangqing:"Kami berbesar hati kerana disenaraikan dalam ‘World’s Most Admired Companies’ oleh Fortune selama 12 tahun berturut-turut, serta menduduki tempat pertama dalam industri sekuriti dan pengurusan aset.",weishenme:"Mengapa memilih RWA?",weishenmexiangqing:"Semakin ramai pelabur mempercayai RWA kerana kami menawarkan lebih banyak pilihan berbanding syarikat lain dalam industri. Platform global kami direka untuk membantu pelanggan mencapai matlamat kewangan terpenting mereka.",weishenmexiangqing1:"Aliran masuk bersih sebanyak USD 1.8 trilion dalam tempoh 5 tahun",weishenmexiangqing2:"Membantu lebih 35 juta rakyat Amerika melabur dan menabung untuk persaraan",weishenmexiangqing3:"Lebih 190,000 penasihat kewangan di AS memilih RWA",huoban:"Rakan Kongsi",huobanxiangqing:"Dalam beberapa tahun kebelakangan ini, RWA telah melabur secara aktif dalam bidang kecerdasan buatan (AI), merangkumi infrastruktur, teknologi cip, analisis data dan pembangunan mampan.",huoban1:"Perkongsian Pelaburan Infrastruktur AI Global (AIP)",huoban11:"Pada September 2024, RWA bersama Microsoft, Mubadala dan GIP melancarkan AIP untuk melabur lebih USD 30 bilion dalam infrastruktur.",huoban2:"Pelaburan dalam syarikat pemula cip AI Groq",huoban22:"Pada Ogos 2024, RWA mengetuai pembiayaan USD 640 juta untuk Groq.",huoban3:"Pelaburan dalam syarikat analitik AI Pyramid Analytics",huoban33:"Pada November 2024, RWA melabur USD 50 juta dalam Pyramid Analytics.",huoban4:"Perkongsian strategik dengan Clarity AI",huoban44:"Sejak 2021, RWA telah melabur dalam Clarity AI dan mengintegrasikan teknologinya ke dalam platform Aladdin.",huoban5:"Melalui kerjasama ini, RWA memperkukuh kedudukannya dalam ekosistem AI.",chongti:"Deposit & Pengeluaran Pantas",chongtixiangqing:"Menyokong pelbagai kaedah pembayaran untuk deposit dan pengeluaran pantas",huanying:"Selamat datang ke perkhidmatan RWA",baipishu:"Kertas Putih",chengyuandengjice:"Daftar Ahli",gongsizhangcheng:"Perlembagaan Syarikat",gupiaozhengshu:"Sijil Saham",huiyijilu:"Minit Mesyuarat",zhucezhengshu:"Sijil Pendaftaran",shuihao:"Nombor Cukai",weijiaoyiersheng:"Dicipta untuk Dagangan",guanlianzhanghu:"Akaun Berkaitan",yizhixingdingdan:"Pesanan Dilaksanakan",xinwen:"Berita",cishan:"Kebajikan",efepeishou:"Peruntukan ETF",rineijiaoyi:"Dagangan Harian"}};export{a as default};
